export function getChapterById(id) {
  return COURSEWARE.chapters.find((c) => c.id === id) ?? null;
}

export function getChallengesByChapter(chapterId) {
  const chapter = getChapterById(chapterId);
  return chapter?.linkedChallenges ?? [];
}
